module sample_rate_converter(
    input clk,
    input reset,
    input [7:0] din,
    output reg [7:0] dout
);
    reg [1:0] count;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            dout <= 8'b0;
            count <= 2'b0;
        end else begin
            if (count == 2'b01) begin
                dout <= din; // Output the input value every 2 clock cycles
                count <= 2'b00;
            end else begin
                count <= count + 1;
            end
        end
    end
endmodule

