module pll(input clk_ref, input clk_fb, output reg clk_out);  
  reg [1:0] state;  
  parameter LOCKED = 2'b00, ADJUST = 2'b01, UNLOCKED = 2'b10;  

  always @(posedge clk_ref or posedge clk_fb) begin  
    if (clk_fb) begin  
      state <= LOCKED;  
      clk_out <= clk_ref;  
    end  
    else if (state == LOCKED) begin  
      // Adjust phase if not locked  
      clk_out <= ~clk_out;  
      state <= ADJUST;  
    end  
    else if (state == ADJUST) begin  
      // Stay in adjust state until locked  
      if (clk_fb)  
        state <= LOCKED;  
    end  
  end  
endmodule

