module serializer (
    input clk,
    input rst,
    input start,
    input [31:0] data_in,
    output reg serialized_out
);

    reg [4:0] bit_index; // 5 bits to count 0 to 31
    reg serializing;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            serialized_out <= 0;
            bit_index <= 0;
            serializing <= 0;
        end else begin
            if (start) begin
                serializing <= 1;
                bit_index <= 0;
            end
            if (serializing) begin
                serialized_out <= data_in[31 - bit_index]; // serialize MSB first
                bit_index <= bit_index + 1;
                if (bit_index == 31) begin
                    serializing <= 0; // stop serialization after 32 bits
                end
            end
        end
    end
endmodule

