        4'b1001: Y = I[9];
        4'b1010: Y = I[10];
        4'b1011: Y = I[11];
        4'b1100: Y = I[12];
        4'b1101: Y = I[13];
        4'b1110: Y = I[14];
        4'b1111: Y = I[15];
        default: Y = 1'b0; // Default case
    endcase
end

endmodule

