module divide_by_4 (
    input clk,
    input reset,
    input [1:0] in,
    output reg out
);
    reg [1:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 2'b00;
            out <= 1'b0;
        end else begin
            count <= count + 1;
            if (count == 2'b11) begin
                out <= in[0];  // output the LSB of input on every fourth clock cycle
            end
        end
    end
endmodule

