module uart_transmitter (
    input wire clk,              // 50 MHz clock
    input wire start,            // Start signal to begin transmission
    input wire [7:0] data_in,    // 8-bit data input
    output reg tx,              // Serial data output
    output reg busy             // Signal active when transmission is ongoing
);

    reg [3:0] bit_count;         // Bit counter
    reg [9:0] shift_reg;         // Shift register for transmission
    reg [15:0] baud_counter;     // Baud rate counter
    reg state;                   // State of the transmitter

    localparam IDLE = 1'b0;
    localparam SEND = 1'b1;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                tx <= 1; // Idle state is high
                busy <= 0;
                if (start) begin
                    shift_reg <= {1'b1, data_in, 1'b0}; // Start bit, data, stop bit
                    bit_count <= 0;
                    baud_counter <= 0;
                    busy <= 1;
                    state <= SEND;
                end
            end

            SEND: begin
                if (baud_counter == 16'd520) begin // Adjust based on clock frequency
                    tx <= shift_reg[0]; // Send the current bit
                    shift_reg <= shift_reg >> 1; // Shift right
                    bit_count <= bit_count + 1;
                    baud_counter <= 0;
                    if (bit_count == 9) begin // After sending 10 bits (1 start + 8 data + 1 stop)
                        busy <= 0;
                        state <= IDLE; // Go back to IDLE state
                    end
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
        endcase
    end
endmodule

