module temp_shutdown_controller(  
    input wire clk,  
    input wire rst,  
    input wire [7:0] temp,  
    output reg shutdown  
);  
    reg [1:0] state;  
    parameter THRESHOLD_HIGH = 8'd75;  
    parameter THRESHOLD_LOW = 8'd70;  
    parameter WAIT_TIME = 3;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            shutdown <= 0;  
            state <= 0;  
        end else begin  
            case (state)  
                0: begin  
                    if (temp > THRESHOLD_HIGH) begin  
                        state <= 1;  
                    end  
                end  
                1: begin  
                    if (temp <= THRESHOLD_HIGH) begin  
                        state <= 0;  
                        shutdown <= 0;  
                    end else begin  
                        shutdown <= 1;  
                        state <= 2;  
                    end  
                end  
                2: begin  
                    if (temp <= THRESHOLD_LOW) begin  
                        shutdown <= 0;  
                        state <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

module floyd_warshall #(parameter N = 4, parameter INF = 8'hFF) (  
    input [N*N*8-1:0] adj_matrix,  
    output reg [N*N*8-1:0] dist_matrix  
);  
    integer i, j, k;  
    reg [7:0] dist [0:N-1][0:N-1];  

    always @(*) begin  
        // Initialize distance matrix  
        for (i = 0; i < N; i = i + 1) begin  
            for (j = 0; j < N; j = j + 1) begin  
                if (i == j)  
                    dist[i][j] = 8'h00;  
                else  
                    dist[i][j] = adj_matrix[(i*N + j)*8 +: 8];  
            end  
        end  

        // Floyd-Warshall algorithm  
        for (k = 0; k < N; k = k + 1) begin  
            for (i = 0; i < N; i = i + 1) begin  
                for (j = 0; j < N; j = j + 1) begin  
                    if (dist[i][k] != INF && dist[k][j] != INF &&  
                        dist[i][j] > dist[i][k] + dist[k][j])  
                        dist[i][j] = dist[i][k] + dist[k][j];  
                end  
            end  
        end  

        // Assign output  
        for (i = 0; i < N; i = i + 1) begin  
            for (j = 0; j < N; j = j + 1) begin  
                dist_matrix[(i*N + j)*8 +: 8] = dist[i][j];  
            end  
        end  
    end  
endmodule

