module pipeline_processor (
    input clk,
    input rst,
    input [7:0] operand_a,
    input [7:0] operand_b,
    output reg [7:0] result
);

    reg [7:0] IF_reg_a, IF_reg_b;
    reg [7:0] ID_reg_a, ID_reg_b;
    reg [7:0] EX_result;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 8'd0;
            IF_reg_a <= 8'd0;
            IF_reg_b <= 8'd0;
            ID_reg_a <= 8'd0;
            ID_reg_b <= 8'd0;
            EX_result <= 8'd0;
        end else begin
            // Pipeline stages
            // IF stage
            IF_reg_a <= operand_a;
            IF_reg_b <= operand_b;

            // ID stage
            ID_reg_a <= IF_reg_a;
            ID_reg_b <= IF_reg_b;

            // EX stage
            EX_result <= ID_reg_a + ID_reg_b;

            // MEM stage (no memory operation in this simple case)

            // WB stage
            result <= EX_result;
        end
    end
endmodule

