module hazard_detection (
    input wire A,
    input wire B,
    output wire F
);
    wire notA, notB;
    wire A_and_B, A_and_notB, notA_and_B;

    // Generate complements
    not (notA, A);
    not (notB, B);

    // Generate terms
    and (A_and_B, A, B);
    and (A_and_notB, A, notB);
    and (notA_and_B, notA, B);

    // Final output with hazard resolution
    assign F = (A_and_B) | (A_and_notB) | (notA_and_B);
endmodule

