module freq_divider(
    input clk,
    input rst,
    output reg divided_clk
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            divided_clk <= 0;
        end else begin
            divided_clk <= ~divided_clk;
        end
    end
endmodule
